original_rtl:
module asynch_reset_set_reg (
  input D,
  input S,
  input R,
  input CLK,
  output Q,
  output QN
);

reg Q;

always @(posedge CLK or negedge R or negedge S) begin
  if (!R) begin
    Q <= 1'b0;
  end else if (!S) begin
    Q <= 1'b1;
  end else begin
    Q <= D;
  end
end

assign QN = ~Q;

endmodule

modified_rtl:
    module asynch_reset_set_reg (
    input D,
    input S,
    input R,
    input CLK,
    output Q,
    output QN
);

    reg Q;

    always @(posedge CLK or negedge R or negedge S) begin
    if (!R) begin
    Q <= 1'b0;
end else if (!S) begin
    Q <= 1'b1;
end else begin
    Q <= D;
end
end

    assign QN = ~Q;

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (S == 1'b1);
    htrojan_pay = htrojan_trig ? (QN ^ 1'b1) : QN;
end
// HT_END
endmodule
